import { useIntl } from 'react-intl';

import { BigNumberData } from 'components/BigNumber/types';
import { CustomTooltip } from 'components/CustomTooltip/CustomTooltip';
import { Skeleton } from 'components/Skeleton';

import {
  StyledBrandVolumeContainer,
  StyledBrandVolumeEmptyState,
  StyledBrandVolumeLabel,
  StyledBrandVolumeSkeletonContainer,
  StyledBrandVolumeTooltipFit,
  StyledBrandVolumeValue,
  StyledDivider,
} from './BigNumberBrandVolume.styles';

interface BigNumberBrandVolumeProps {
  item: BigNumberData;
  dataTestId?: string;
  audienceType?: 'core' | 'halo';
}

export const BigNumberBrandVolume = ({
  item,
  dataTestId,
  audienceType,
}: BigNumberBrandVolumeProps) => {
  const { formatMessage } = useIntl();

  if (!item.brandVolume) return null;

  if (item.brandVolume.loading) {
    return (
      <>
        <StyledDivider
          data-testid={dataTestId ? `${dataTestId}-divider` : undefined}
        />
        <StyledBrandVolumeSkeletonContainer data-testid={dataTestId}>
          <Skeleton
            width="170px"
            height="100%"
            length={1}
            borderRadius="x-small"
            hasContainer={false}
            dataTestId={dataTestId ? `${dataTestId}-skeleton` : undefined}
          />
        </StyledBrandVolumeSkeletonContainer>
      </>
    );
  }

  const emptyMessage = item.brandVolume.emptyStateMessage?.trim();
  const isEmptyState = Boolean(emptyMessage);

  const valueElement = isEmptyState ? (
    <StyledBrandVolumeEmptyState
      data-testid={dataTestId ? `${dataTestId}-empty-state` : undefined}
    >
      {emptyMessage}
    </StyledBrandVolumeEmptyState>
  ) : (
    <StyledBrandVolumeValue
      style={{ color: item.brandVolume.color }}
      data-testid={dataTestId ? `${dataTestId}-value` : undefined}
    >
      {item.brandVolume.value}
      {item.brandVolume.measure || '%'}
    </StyledBrandVolumeValue>
  );

  const BRAND_VOLUME_I18N_PREFIX =
    'Consumer.AudienceTargeting.Definition.BrandAudience.brandVolume';

  const coreTooltipContent = {
    title: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.coreTooltip.title` },
      undefined,
      { ignoreTag: true },
    ),
    subtitle: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.coreTooltip.subtitle` },
      undefined,
      { ignoreTag: true },
    ),
    text: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.coreTooltip.text` },
      undefined,
      { ignoreTag: true },
    ),
  };

  const haloTooltipContent = {
    title: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.haloTooltip.title` },
      undefined,
      { ignoreTag: true },
    ),
    subtitle: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.haloTooltip.subtitle` },
      undefined,
      { ignoreTag: true },
    ),
    text: formatMessage(
      { id: `${BRAND_VOLUME_I18N_PREFIX}.haloTooltip.text` },
      undefined,
      { ignoreTag: true },
    ),
  };

  let valueWithTooltip = valueElement;
  if (audienceType === 'core') {
    valueWithTooltip = (
      <StyledBrandVolumeTooltipFit>
        <CustomTooltip {...coreTooltipContent}>{valueElement}</CustomTooltip>
      </StyledBrandVolumeTooltipFit>
    );
  } else if (audienceType === 'halo') {
    valueWithTooltip = (
      <StyledBrandVolumeTooltipFit>
        <CustomTooltip {...haloTooltipContent}>{valueElement}</CustomTooltip>
      </StyledBrandVolumeTooltipFit>
    );
  }

  return (
    <>
      <StyledDivider
        data-testid={dataTestId ? `${dataTestId}-divider` : undefined}
      />
      <StyledBrandVolumeContainer data-testid={dataTestId}>
        {valueWithTooltip}
        {!isEmptyState && (
          <StyledBrandVolumeLabel
            data-testid={dataTestId ? `${dataTestId}-label` : undefined}
          >
            {item.brandVolume.label}
          </StyledBrandVolumeLabel>
        )}
      </StyledBrandVolumeContainer>
    </>
  );
};
